import React, { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';
import AddCameraModal from './AddCameraModal';

export default function TopBar({ activePage, setActivePage }) {
  const { stats, alerts, wsConnected } = useApp();
  const [time,      setTime]      = useState('');
  const [showModal, setShowModal] = useState(false);
  const [showMenu,  setShowMenu]  = useState(false);

  const unreadAlerts = alerts.filter(a => !a.acknowledged).length;

  useEffect(() => {
    const tick = () => {
      const n  = new Date();
      let h    = n.getHours();
      let m    = n.getMinutes();
      let s    = n.getSeconds();
      const ap = h >= 12 ? 'PM' : 'AM';
      h = h % 12 || 12;
      const p  = v => v.toString().padStart(2, '0');
      const months = [
        'Jan','Feb','Mar','Apr','May','Jun',
        'Jul','Aug','Sep','Oct','Nov','Dec'
      ];
      const dateStr = `${months[n.getMonth()]} ${n.getDate()}, ${n.getFullYear()}`;
      setTime(`${dateStr}  |  ${p(h)}:${p(m)}:${p(s)} ${ap}`);
    };
    tick();
    const id = setInterval(tick, 1000);
    return () => clearInterval(id);
  }, []);

  return (
    <>
      <div style={{
        display:        'flex',
        alignItems:     'center',
        justifyContent: 'space-between',
        padding:        '10px 16px',
        borderBottom:   '1px solid #1e2d47',
        background:     '#111827',
        flexShrink:     0
      }}>
        {/* Left — Logo */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
          <span style={{ fontSize: 20, color: '#3b82f6' }}>🛡</span>
          <span style={{
            fontSize:      14,
            fontWeight:    700,
            color:         '#3b82f6',
            letterSpacing: '.5px'
          }}>
            BRAWL DETECTION SYSTEM
          </span>
          {/* Connection status */}
          <span style={{
            fontSize:     9,
            background:   wsConnected ? '#0d2010' : '#2d0a0a',
            color:        wsConnected ? '#4ade80' : '#f87171',
            padding:      '2px 7px',
            borderRadius: 10,
            fontWeight:   600
          }}>
            {wsConnected ? '● LIVE' : '● OFFLINE'}
          </span>
        </div>

        {/* Right */}
        <div style={{
          display:    'flex',
          alignItems: 'center',
          gap:        16
        }}>
          {/* Clock */}
          <span style={{ fontSize: 11, color: '#94a3b8' }}>{time}</span>

          {/* Bell with badge */}
          <div style={{ position: 'relative', cursor: 'pointer' }}
            onClick={() => setActivePage && setActivePage('Alerts')}
          >
            <span style={{ fontSize: 18 }}>🔔</span>
            {unreadAlerts > 0 && (
              <span style={{
                position:     'absolute',
                top:          -4, right: -4,
                background:   '#ef4444',
                color:        '#fff',
                fontSize:     8,
                fontWeight:   700,
                width:        16, height: 16,
                borderRadius: '50%',
                display:      'flex',
                alignItems:   'center',
                justifyContent: 'center',
                border:       '1px solid #111827'
              }}>
                {unreadAlerts > 9 ? '9+' : unreadAlerts}
              </span>
            )}
          </div>

          {/* Admin menu */}
          <div style={{ position: 'relative' }}>
            <div
              onClick={() => setShowMenu(!showMenu)}
              style={{
                display:    'flex',
                alignItems: 'center',
                gap:        6,
                cursor:     'pointer',
                padding:    '4px 8px',
                borderRadius: 6,
                background: showMenu ? '#1e2d47' : 'transparent'
              }}
            >
              <div style={{
                width:        28, height: 28,
                borderRadius: '50%',
                background:   '#1e3a5f',
                display:      'flex',
                alignItems:   'center',
                justifyContent: 'center',
                fontSize:     12, fontWeight: 700,
                color:        '#60a5fa'
              }}>A</div>
              <span style={{ fontSize: 12, color: '#94a3b8' }}>Admin</span>
              <span style={{ fontSize: 10, color: '#64748b' }}>▾</span>
            </div>

            {/* Dropdown */}
            {showMenu && (
              <div style={{
                position:     'absolute',
                top:          '110%', right: 0,
                background:   '#0f172a',
                border:       '1px solid #253550',
                borderRadius: 8,
                overflow:     'hidden',
                zIndex:       200,
                minWidth:     160,
                boxShadow:    '0 8px 24px rgba(0,0,0,.7)'
              }}>
                <div style={{
                  padding:      '10px 14px',
                  borderBottom: '1px solid #1e2d47'
                }}>
                  <div style={{ fontSize: 12, fontWeight: 600, color: '#fff' }}>
                    Admin User
                  </div>
                  <div style={{ fontSize: 10, color: '#64748b' }}>
                    admin@brawldetect.com
                  </div>
                  <span style={{
                    fontSize:     9, fontWeight: 700,
                    background:   '#450a0a', color: '#f87171',
                    padding:      '1px 6px', borderRadius: 3,
                    display:      'inline-block', marginTop: 4
                  }}>Admin</span>
                </div>
                {[
                  { icon: '👤', label: 'Profile',  page: 'Users'    },
                  { icon: '⚙',  label: 'Settings', page: 'Settings' },
                  { icon: '📄', label: 'Logs',     page: 'Logs'     },
                ].map((item, i) => (
                  <div
                    key={i}
                    onClick={() => {
                      setActivePage && setActivePage(item.page);
                      setShowMenu(false);
                    }}
                    style={{
                      padding:      '9px 14px',
                      fontSize:     11,
                      color:        '#94a3b8',
                      cursor:       'pointer',
                      display:      'flex',
                      alignItems:   'center',
                      gap:          8,
                      borderBottom: i < 2 ? '1px solid #1e2d47' : 'none'
                    }}
                    onMouseEnter={e => e.currentTarget.style.background = '#1a2340'}
                    onMouseLeave={e => e.currentTarget.style.background = 'transparent'}
                  >
                    {item.icon} {item.label}
                  </div>
                ))}
              </div>
            )}
          </div>

          {/* Add Camera */}
          <button
            onClick={() => setShowModal(true)}
            style={{
              background:   '#3b82f6',
              color:        '#fff',
              border:       'none',
              padding:      '7px 14px',
              borderRadius: 6,
              fontSize:     11,
              fontWeight:   600,
              cursor:       'pointer',
              display:      'flex',
              alignItems:   'center',
              gap:          4
            }}
          >
            + Add Camera
          </button>
        </div>
      </div>

      {showModal && (
        <AddCameraModal onClose={() => setShowModal(false)} />
      )}
    </>
  );
}
